#include <stdio.h>
#include <openssl/crypto.h>
#include <openssl/ssl.h>
#include <openssl/opensslv.h>
int main(void) {
    unsigned long runtime = OpenSSL_version_num();
    int has_ssl_method = TLS_method() != NULL;
    printf("header=%s\nruntime=%s\nheader_number=%lx\nruntime_number=%lx\nssl_method_available=%d\n",
           OPENSSL_VERSION_TEXT, OpenSSL_version(OPENSSL_VERSION),
           (unsigned long)OPENSSL_VERSION_NUMBER, runtime, has_ssl_method);
    return OPENSSL_VERSION_NUMBER == 0x30500090L && runtime == 0x30500090L && has_ssl_method ? 0 : 1;
}
